class Solution {
public:
    int shortestPathAllKeys(vector<string>& grid) {
        int m = grid.size(), n = grid[0].size();
        int start_r = 0, start_c = 0, total_keys = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                char ch = grid[i][j];
                if (ch == '@') {
                    start_r = i; start_c = j;
                } else if (ch >= 'a' && ch <= 'f') {
                    total_keys = max(total_keys, ch - 'a' + 1);
                }
            }
        }
        int target_mask = (1 << total_keys) - 1;
        queue<tuple<int, int, int, int>> q;
        vector<vector<vector<bool>>> visited(m, vector<vector<bool>>(n, vector<bool>(1 << total_keys, false)));
        q.push({start_r, start_c, 0, 0});
        visited[start_r][start_c][0] = true;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.empty()) {
            auto [r, c, mask, dist] = q.front();
            q.pop();
            if (mask == target_mask) return dist;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    char ch = grid[nr][nc];
                    if (ch == '#') continue;
                    if (ch >= 'A' && ch <= 'F' && !(mask & (1 << (ch - 'A')))) continue;
                    int nmask = mask;
                    if (ch >= 'a' && ch <= 'f') nmask |= (1 << (ch - 'a'));
                    if (!visited[nr][nc][nmask]) {
                        visited[nr][nc][nmask] = true;
                        q.push({nr, nc, nmask, dist + 1});
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int shortestPathAllKeys(String[] grid) {
        int m = grid.length, n = grid[0].length();
        int startR = 0, startC = 0, totalKeys = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                char ch = grid[i].charAt(j);
                if (ch == '@') {
                    startR = i; startC = j;
                } else if (ch >= 'a' && ch <= 'f') {
                    totalKeys = Math.max(totalKeys, ch - 'a' + 1);
                }
            }
        }
        int targetMask = (1 << totalKeys) - 1;
        Queue<int[]> q = new LinkedList<>();
        boolean[][][] visited = new boolean[m][n][1 << totalKeys];
        q.offer(new int[]{startR, startC, 0, 0});
        visited[startR][startC][0] = true;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int r = curr[0], c = curr[1], mask = curr[2], dist = curr[3];
            if (mask == targetMask) return dist;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    char ch = grid[nr].charAt(nc);
                    if (ch == '#') continue;
                    if (ch >= 'A' && ch <= 'F' && (mask & (1 << (ch - 'A'))) == 0) continue;
                    int nmask = mask;
                    if (ch >= 'a' && ch <= 'f') nmask |= (1 << (ch - 'a'));
                    if (!visited[nr][nc][nmask]) {
                        visited[nr][nc][nmask] = true;
                        q.offer(new int[]{nr, nc, nmask, dist + 1});
                    }
                }
            }
        }
        return -1;
    }
}

var shortestPathAllKeys = function(grid) {
    const m = grid.length, n = grid[0].length;
    let startR = 0, startC = 0, totalKeys = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const ch = grid[i][j];
            if (ch === '@') {
                startR = i; startC = j;
            } else if (ch >= 'a' && ch <= 'f') {
                totalKeys = Math.max(totalKeys, ch.charCodeAt(0) - 97 + 1);
            }
        }
    }
    const targetMask = (1 << totalKeys) - 1;
    const q = [[startR, startC, 0, 0]];
    const visited = new Set([`${startR},${startC},0`]);
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (q.length > 0) {
        const [r, c, mask, dist] = q.shift();
        if (mask === targetMask) return dist;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                const ch = grid[nr][nc];
                if (ch === '#') continue;
                if (ch >= 'A' && ch <= 'F' && !(mask & (1 << (ch.charCodeAt(0) - 65)))) continue;
                let nmask = mask;
                if (ch >= 'a' && ch <= 'f') {
                    nmask |= (1 << (ch.charCodeAt(0) - 97));
                }
                const key = `${nr},${nc},${nmask}`;
                if (!visited.has(key)) {
                    visited.add(key);
                    q.push([nr, nc, nmask, dist + 1]);
                }
            }
        }
    }
    return -1;
};
